import Foundation
@main struct HeartbeatChecks {
    static func main() throws {
        let now=Date(timeIntervalSince1970:1_791_280_000)
        var progressSteps=PAHeartbeatRules.stages()
        precondition(PAHeartbeatProgress(runID:"first",steps:progressSteps).percentage == 0)
        progressSteps[0].status="waiting";progressSteps[1].status="skipped";progressSteps[2].status="failed"
        progressSteps[3].status="running"
        let half=PAHeartbeatProgress(runID:"first",steps:progressSteps)
        precondition(half.percentage == 50 && half.stage == "Memory & organisation","Optional unavailable/failed work advances stage progress without estimating request time")
        for index in progressSteps.indices {progressSteps[index].status="done"}
        precondition(PAHeartbeatProgress(runID:"first",steps:progressSteps).percentage == 99,"Finishing stages alone cannot claim the final save")
        precondition(PAHeartbeatProgress(runID:"first",steps:progressSteps,finished:true).percentage == 100)
        precondition(PAHeartbeatProgress(runID:"second",steps:PAHeartbeatRules.stages()).percentage == 0,"A new run starts at zero")
        precondition(PAHeartbeatProgress(runID:"empty",steps:[],finished:true).percentage == 0)
        precondition(PAHeartbeatRules.currentCompletion(collectedRevision:4,currentRevision:4,collectedAt:now.addingTimeInterval(-100),now:now))
        precondition(!PAHeartbeatRules.currentCompletion(collectedRevision:3,currentRevision:4,collectedAt:now,now:now),"Reopened reminders cannot use old completed evidence")
        precondition(!PAHeartbeatRules.currentCompletion(collectedRevision:-1,currentRevision:-1,collectedAt:now,now:now))
        precondition(!PAHeartbeatRules.currentCompletion(collectedRevision:4,currentRevision:4,collectedAt:now.addingTimeInterval(-1800),now:now))
        precondition(!PAHeartbeatRules.currentCompletion(collectedRevision:4,currentRevision:4,collectedAt:nil,now:now))
        var account=PAHeartbeatAccount()
        precondition(PAHeartbeatRules.due(account,now:now))
        account.checked=now
        precondition(!PAHeartbeatRules.due(account,now:now.addingTimeInterval(1799),minutes:30))
        precondition(PAHeartbeatRules.due(account,now:now.addingTimeInterval(1800),minutes:30))
        account.fingerprint="same"
        precondition(PAHeartbeatRules.needsAssessment(account,fingerprint:"same",manual:false),"A due heartbeat reviews unchanged context too")
        precondition(PAHeartbeatRules.needsAssessment(account,fingerprint:"same",manual:false,pendingSources:true))
        precondition(PAHeartbeatRules.needsAssessment(account,fingerprint:"new",manual:false))
        account.phase="assessing"
        let recovered=PAHeartbeatRules.recovered(account,now:now)
        precondition(PAHeartbeatRules.due(recovered,now:now.addingTimeInterval(86400*3)),"Interrupted assessment catches up with one fresh run after wake")
        precondition(recovered.phase == "idle" && recovered.retryReason == "failure" && recovered.checked == account.checked && recovered.fingerprint == "same")
        precondition(PAHeartbeatRules.needsAssessment(recovered,fingerprint:"new",manual:false))
        precondition(PAHeartbeatRules.needsAssessment(recovered,fingerprint:"same",manual:false,pendingSources:true))
        precondition(PAHeartbeatRules.needsAssessment(recovered,fingerprint:"same",manual:true,pendingSources:true))
        precondition(PAHeartbeatRules.needsAssessment(recovered,fingerprint:"new",manual:true))
        var state=PAHeartbeatState(accounts:["a":recovered,"b":PAHeartbeatAccount()])
        state=try JSONDecoder().decode(PAHeartbeatState.self,from:JSONEncoder().encode(state))
        precondition(state.accounts["a"]?.phase == "idle" && PAHeartbeatRules.due(state.accounts["b"]!,now:now))
        precondition(!PAHeartbeatRules.due(account,now:now.addingTimeInterval(3599),minutes:60))
        precondition(PAHeartbeatRules.due(account,now:now.addingTimeInterval(3600),minutes:60))
        precondition(PAHeartbeatRules.due(account,now:now.addingTimeInterval(900),minutes:15))
        precondition(PAHeartbeatRules.callLimit(nil) == 0 && PAHeartbeatRules.callLimit(0) == 0)
        precondition(PAHeartbeatRules.callLimit(32) == 32 && PAHeartbeatRules.callLimit(64) == 64)
        var unlimited=PAHeartbeatAccount()
        for _ in 0..<120 {unlimited=try PAHeartbeatRules.claim(unlimited,day:"2026-10-06",limit:0)}
        precondition(unlimited.calls == 120,"Off keeps counting without an implicit daily ceiling")
        var budget=PAHeartbeatAccount()
        budget=try PAHeartbeatRules.claim(budget,day:"2026-10-06",limit:2)
        budget=try PAHeartbeatRules.claim(budget,day:"2026-10-06",limit:2)
        do { _ = try PAHeartbeatRules.claim(budget,day:"2026-10-06",limit:2);preconditionFailure("Allowance exceeded") } catch is HeartbeatBudgetExhausted {}
        precondition(PAHeartbeatRules.callCount(budget,day:"2026-10-06") == 2)
        budget.pending=true
        precondition(PAHeartbeatRules.needsAssessment(budget,fingerprint:budget.fingerprint ?? "",manual:false))
        budget.phase="paused"
        precondition(!PAHeartbeatRules.needsAssessment(budget,fingerprint:"new",manual:false))
        budget.phase="idle"
        let next=try PAHeartbeatRules.claim(budget,day:"2026-10-07",limit:2)
        precondition(next.calls == 1 && next.budgetDay == "2026-10-07")
        let savedBudget=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(budget))
        precondition(savedBudget.calls == 2 && savedBudget.phase == "idle")
        var lanes=PAHeartbeatRules.collectingMail(budget,enabled:["healthy","failed"],ready:["healthy"],issues:["failed":"timeout"],now:now)
        lanes=PAHeartbeatRules.completedMail(lanes,fingerprints:["healthy":"opaque-v1"],pending:[],now:now)
        precondition(lanes.mailLanes?["healthy"]?.assessed == now && lanes.mailLanes?["healthy"]?.pending == false)
        precondition(lanes.mailLanes?["failed"]?.assessed == nil && lanes.mailLanes?["failed"]?.issue == "timeout" && lanes.mailLanes?["failed"]?.pending == true)
        let reopened=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(lanes))
        precondition(reopened.mailLanes?["healthy"]?.fingerprint == "opaque-v1" && reopened.mailLanes?["failed"]?.issue == "timeout")
        lanes=PAHeartbeatRules.collectingMail(reopened,enabled:["healthy","failed"],ready:["healthy","failed"],issues:[:],now:now.addingTimeInterval(3600))
        precondition(lanes.mailLanes?["failed"]?.pending == true && lanes.mailLanes?["failed"]?.assessed == nil,"Collection alone never marks failed account assessed")
        lanes=PAHeartbeatRules.completedMail(lanes,fingerprints:["failed":"opaque-recovered"],pending:["failed"],now:now.addingTimeInterval(3600))
        precondition(lanes.mailLanes?["failed"]?.assessed == now.addingTimeInterval(3600) && lanes.mailLanes?["healthy"]?.assessed == now)
        let stopped=PAHeartbeatRules.recovered(PAHeartbeatAccount(phase:"assessing",mailLanes:lanes.mailLanes))
        precondition(stopped.phase == "idle" && stopped.retryReason == "failure" && stopped.mailLanes?["failed"]?.fingerprint == "opaque-recovered")
        let narrowed=PAHeartbeatRules.collectingMail(lanes,enabled:["healthy"],ready:["healthy"],issues:[:],now:now)
        precondition(narrowed.mailLanes?.count == 1 && narrowed.calls == lanes.calls)
        let legacy=try JSONDecoder().decode(PAHeartbeatAccount.self,from:Data(#"{"phase":"idle"}"#.utf8))
        precondition(legacy.mailLanes == nil)
        let run=PAReviewRun(id:"run",started:now,finished:now,manual:true,phase:"paused",detail:"Rejected target",calls:2,checkedAccounts:1,waitingAccounts:1,preparedItems:0,drafts:1,handled:0)
        var collectedRun=run;collectedRun.phase="waiting";collectedRun.briefUpdated=true;collectedRun.mailCollectionIndependent=true
        precondition(collectedRun.outcome() == "Completed" && collectedRun.summary.contains("Mail collection issue") && !collectedRun.summary.contains("accounts waiting"),"Completed analysis reports collection issues separately")
        let cachedLane=PAHeartbeatRules.completedMail(lanes,fingerprints:["healthy":"collected-v2"],pending:[],now:now,issues:["healthy":"Background arrival check unfinished"])
        precondition(cachedLane.mailLanes?["healthy"]?.assessed == now && cachedLane.mailLanes?["healthy"]?.issue != nil && cachedLane.mailLanes?["healthy"]?.pending == true,"AI completion retains separate collection coverage and pending work")
        let retainedRun=try JSONDecoder().decode(PAReviewRun.self,from:JSONEncoder().encode(collectedRun))
        precondition(retainedRun.mailCollectionIndependent == true && run.mailCollectionIndependent == nil,"New history metadata is additive; old history retains its wording")
        let activity=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(PAHeartbeatAccount(phase:"paused",reviews:[run])))
        precondition(activity.reviews?.first?.calls == 2 && activity.reviews?.first?.detail == "Rejected target" && legacy.reviews == nil)
        let interruptedCollection=PAHeartbeatRules.interrupted(PAHeartbeatAccount(checked:now,phase:"refreshing",budgetDay:"2026-10-06",calls:1,mailLanes:lanes.mailLanes,reviews:[run]),now:now,foreground:true)
        precondition(interruptedCollection.phase == "idle" && interruptedCollection.pending == true && interruptedCollection.retryReason == "foreground")
        precondition(!PAHeartbeatRules.due(interruptedCollection,now:now.addingTimeInterval(59)))
        precondition(PAHeartbeatRules.due(interruptedCollection,now:now.addingTimeInterval(60)),"An idle retry must not consume a whole hourly review interval")
        precondition(interruptedCollection.calls == 1 && interruptedCollection.mailLanes?["failed"]?.fingerprint == lanes.mailLanes?["failed"]?.fingerprint && interruptedCollection.reviews?.first?.id == run.id)
        let restoredCollection=PAHeartbeatRules.recovered(PAHeartbeatAccount(checked:now,phase:"refreshing"),now:now)
        precondition(restoredCollection.phase == "idle" && restoredCollection.retryAfter == now.addingTimeInterval(300))
        let interruptedInference=PAHeartbeatRules.interrupted(PAHeartbeatAccount(checked:now,phase:"assessing",retryAfter:now),now:now,foreground:true)
        precondition(interruptedInference.phase == "idle" && interruptedInference.retryAfter == now.addingTimeInterval(3600))
        precondition(PAHeartbeatRules.needsAssessment(interruptedInference,fingerprint:"changed",manual:false,pendingSources:true),"The next scheduled run captures fresh context")
        precondition(!PAHeartbeatRules.due(interruptedInference,now:now.addingTimeInterval(3599)))
        precondition(PAHeartbeatRules.due(interruptedInference,now:now.addingTimeInterval(3600)))
        var london=Calendar(identifier:.gregorian);london.timeZone=TimeZone(identifier:"Europe/London")!
        let formatter=ISO8601DateFormatter(),nearMidnight=formatter.date(from:"2026-10-06T22:58:00Z")!,midnight=formatter.date(from:"2026-10-06T23:00:00Z")!
        let exhausted=PAHeartbeatRules.deferred(PAHeartbeatAccount(checked:nearMidnight,budgetDay:"2026-10-06",calls:2),now:nearMidnight,reason:.allowance,calendar:london)
        precondition(exhausted.retryAfter == midnight && exhausted.pending == true)
        precondition(PAHeartbeatRules.due(exhausted,now:nearMidnight,day:"2026-10-06",allowance:0),"Turning off the cap releases an existing allowance wait")
        precondition(!PAHeartbeatRules.due(exhausted,now:nearMidnight,day:"2026-10-06",allowance:2))
        let failedWithLimitOff=PAHeartbeatRules.failed(exhausted,now:nearMidnight)
        precondition(!PAHeartbeatRules.due(failedWithLimitOff,now:nearMidnight,day:"2026-10-06",allowance:0),"Off does not bypass failed-run backoff")

        precondition(!PAHeartbeatRules.due(exhausted,now:midnight.addingTimeInterval(-1),day:"2026-10-06"))
        precondition(PAHeartbeatRules.due(exhausted,now:midnight,day:"2026-10-07"),"Day rollover must release pending allowance work without waiting another hour")
        precondition(PAHeartbeatRules.due(exhausted,now:nearMidnight,day:"2026-10-07"),"A timezone change must follow the current local allowance day")
        precondition(PAHeartbeatRules.due(exhausted,now:nearMidnight,day:"2026-10-06",allowance:3),"An explicitly raised allowance releases waiting work")
        let dstDay=formatter.date(from:"2026-10-25T00:30:00Z")!
        let dst=PAHeartbeatRules.deferred(PAHeartbeatAccount(budgetDay:"2026-10-25",calls:2),now:dstDay,reason:.allowance,calendar:london)
        precondition(dst.retryAfter == formatter.date(from:"2026-10-26T00:00:00Z"),"Next local day respects the 25-hour clock-change day")
        let restoredRetry=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(interruptedCollection))
        precondition(restoredRetry.retryAfter == interruptedCollection.retryAfter && restoredRetry.retryReason == "foreground" && legacy.retryAfter == nil)
        let settled=PAHeartbeatRules.clearWait(restoredRetry)
        precondition(settled.retryAfter == nil && !PAHeartbeatRules.due(settled,now:now.addingTimeInterval(60)),"A settled review returns to its configured interval")
        let quietPartial=PAHeartbeatRules.quiet(lanes,fingerprint:"already-checked",ready:["healthy"],pending:true)
        precondition(quietPartial.mailLanes?["healthy"]?.pending == false && quietPartial.mailLanes?["failed"]?.pending == true && quietPartial.pending == true)
        let quietComplete=PAHeartbeatRules.quiet(quietPartial,fingerprint:"already-checked",ready:["healthy","failed"],pending:false)
        precondition(quietComplete.pending == false && quietComplete.mailLanes?["failed"]?.pending == false,"A quiet complete check clears stale waiting flags")
        precondition(quietComplete.assessed == quietPartial.assessed && quietComplete.mailLanes?["healthy"]?.assessed == quietPartial.mailLanes?["healthy"]?.assessed && quietComplete.calls == quietPartial.calls,"Quiet checks never invent an AI review or reset the allowance")
        for minutes in [15,30,60,120] {
            let failed=PAHeartbeatRules.failed(lanes,now:now,minutes:minutes)
            let retry=now.addingTimeInterval(Double(minutes)*60)
            precondition(!PAHeartbeatRules.due(failed,now:retry.addingTimeInterval(-1),minutes:minutes))
            precondition(PAHeartbeatRules.due(failed,now:retry,minutes:minutes))
            precondition(failed.calls == lanes.calls && failed.mailLanes?["healthy"]?.fingerprint == lanes.mailLanes?["healthy"]?.fingerprint)
            let persisted=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(failed))
            precondition(PAHeartbeatRules.recovered(persisted,now:retry.addingTimeInterval(300),minutes:minutes).retryAfter == retry,"Reopening never postpones a due retry")
            var legacyPause=failed;legacyPause.phase="paused";legacyPause.retryAfter=nil;legacyPause.retryReason=nil
            let migrated=PAHeartbeatRules.recovered(legacyPause,now:retry.addingTimeInterval(600),minutes:minutes)
            precondition(migrated.checked == now && migrated.retryAfter == retry && PAHeartbeatRules.due(migrated,now:retry,minutes:minutes))
            let repeated=PAHeartbeatRules.failed(persisted,now:retry,minutes:minutes)
            precondition(!PAHeartbeatRules.due(repeated,now:retry.addingTimeInterval(1),minutes:minutes),"A second failure cannot create an immediate request loop")
        }
        let shorter=PAHeartbeatRules.failed(lanes,now:now,minutes:120)
        precondition(PAHeartbeatRules.nextReview(shorter,now:now,minutes:30) == now.addingTimeInterval(1800),"Retry timing follows a changed interval")
        let slept=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(PAHeartbeatAccount(checked:now,assessed:now)))
        let wake=now.addingTimeInterval(8*3600)
        var interruptedSleep=slept;interruptedSleep.checked=wake;interruptedSleep.calls=7;interruptedSleep.phase="assessing"
        let suspended=PAHeartbeatRules.suspended(interruptedSleep,prior:slept)
        precondition(suspended.checked == slept.checked && suspended.calls == 7 && suspended.phase == "idle" && suspended.pending == true)
        precondition(PAHeartbeatRules.due(suspended,now:wake),"Closing during a due heartbeat must not postpone reopening by a fresh hour")
        let suspendedRestored=try JSONDecoder().decode(PAHeartbeatAccount.self,from:JSONEncoder().encode(suspended))
        precondition(PAHeartbeatRules.due(suspendedRestored,now:wake),"Sleep catch-up survives cache reopening")
        let sleepRun=PAReviewRun(id:"sleep",started:now,finished:wake,manual:false,phase:"suspended",detail:"Laptop closed")
        precondition(sleepRun.outcome() == "Paused for sleep","Sleep is reported distinctly from a failed provider request")
        precondition(PAHeartbeatRules.due(slept,now:wake))
        var caughtUp=slept;caughtUp.checked=wake;caughtUp.assessed=wake
        precondition(!PAHeartbeatRules.due(caughtUp,now:wake.addingTimeInterval(1)),"A missed eight-hour span runs once, not eight times")
        precondition(PAHeartbeatRules.needsAssessment(caughtUp,fingerprint:"same",manual:false))
        let control=UUID()
        precondition(PAHeartbeatRules.canPrepareSources(settings:"same",currentSettings:"same",choices:control,currentChoices:control,identity:"",currentIdentity:"verified"),"Saved connection authentication before inference is ordinary preparation")
        precondition(!PAHeartbeatRules.canPrepareSources(settings:"same",currentSettings:"changed",choices:control,currentChoices:control,identity:"",currentIdentity:"verified"))
        precondition(!PAHeartbeatRules.canPrepareSources(settings:"same",currentSettings:"same",choices:control,currentChoices:UUID(),identity:"",currentIdentity:"verified"),"Human WhatsApp selection changes still cancel preparation")
        precondition(!PAHeartbeatRules.canPrepareSources(settings:"same",currentSettings:"same",choices:control,currentChoices:control,identity:"known",currentIdentity:"different"),"An already known linked identity cannot be retargeted")
        func allowed(owner:String="a",scope:String="permitted",day:String="today",model:String="chosen",controls:UUID? = nil)->Bool {
            PAHeartbeatRules.canContinue(owner:"a",currentOwner:owner,controls:control,currentControls:controls ?? control,scope:"permitted",currentScope:scope,day:"today",currentDay:day,model:"chosen",currentModel:model)
        }
        precondition(allowed(),"Next stage can capture new source content under the same ownership")
        precondition(!allowed(owner:"b") && !allowed(scope:"changed") && !allowed(day:"tomorrow") && !allowed(model:"different") && !allowed(controls:UUID()),"Fresh inputs never widen captured ownership")
        var completed=run;completed.phase="waiting";completed.briefUpdated=true;completed.steps=PAHeartbeatRules.stages();completed.steps?[3].status="done"
        precondition(completed.outcome() == "Completed","Pending source lanes do not relabel a saved brief as a failed heartbeat")
        let newHistory=try JSONDecoder().decode(PAReviewRun.self,from:JSONEncoder().encode(completed))
        precondition(newHistory.steps?[3].status == "done" && newHistory.briefUpdated == true)
        precondition(run.steps == nil && run.failure == nil && run.outcome() == "Stopped")
        var failedHistory=completed;failedHistory.phase="failed"
        precondition(failedHistory.outcome() == "Partly completed")
        failedHistory.briefUpdated=false;precondition(failedHistory.outcome() == "Failed")
        var crashed=completed;crashed.finished=nil
        precondition(crashed.outcome() == "Interrupted" && crashed.outcome(running:true) == "Running")
        print("PASS heartbeat: configurable due boundaries, periodic assessment including unchanged context and single catch-up, persisted daily request allowance, day rollover, captured account isolation and failed/incomplete inference rescheduled with fresh context and preserved receipts")
    }
}
